:root {
    --jlcstrip: color-mix(in srgb, var(--maincolorr) 50%, #000);
    --jlchover: rgba(255, 255, 255, 0.14);
    --jlcfont: "Segoe UI", system-ui, Roboto, "Helvetica Neue", Arial, sans-serif;
}

body { background: var(--jlcstrip); font-family: var(--jlcfont); }
#chrome { background: var(--jlcstrip); color: #fff; font-family: var(--jlcfont); }

#tabrow { height: 41px; padding: 7px 8px 0 0; gap: 0; align-items: flex-end; background: transparent; }
#tabrow #tablist { gap: 0; padding: 0 10px; align-items: flex-end; }

.browsertab {
    position: relative; isolation: isolate;
    flex: 0 1 240px; min-width: 40px; max-width: 240px; height: 34px;
    padding: 0 8px 0 12px; gap: 8px; border-radius: 10px 10px 0 0;
    color: rgba(255, 255, 255, 0.72); background: transparent; font-size: 12px;
    font-family: var(--jlcfont); transition: none;
}
.browsertab:hover { background: transparent; }
.browsertab:not(.active)::before {
    content: ""; position: absolute; inset: 4px 1px; border-radius: 8px; z-index: -1; background: transparent;
}
.browsertab:not(.active):hover::before { background: var(--jlchover); }
.browsertab:not(.active)::after {
    content: ""; position: absolute; right: -1px; top: 10px; bottom: 10px; width: 1px; background: rgba(255, 255, 255, 0.24);
}
.browsertab:hover::after,
.browsertab:has(+ .browsertab.active)::after,
.browsertab:has(+ .browsertab:hover)::after,
.browsertab:last-child::after { opacity: 0; }

.browsertab.active { overflow: visible !important; z-index: 2; color: #fff; background: var(--maincolorr); }
.browsertab.active::before,
.browsertab.active::after { content: ""; position: absolute; bottom: 0; width: 10px; height: 10px; pointer-events: none; z-index: -1; }
.browsertab.active::before { left: -10px; background: radial-gradient(circle at 0 0, transparent 9.5px, var(--maincolorr) 10px); }
.browsertab.active::after { right: -10px; background: radial-gradient(circle at 100% 0, transparent 9.5px, var(--maincolorr) 10px); }

.tabicon { width: 16px; height: 16px; border-radius: 2px; }
.tabtitle { font-size: 12px; color: inherit; }
.tabclose { width: 20px; height: 20px; font-size: 0; color: inherit; border-radius: 50%; }
.tabclose::before { content: "\2715"; font-size: 10px; line-height: 1; }
.tabclose:hover { background: rgba(255, 255, 255, 0.2); }
.browsertab.dropbeforee { box-shadow: inset 3px 0 0 #fff; }
.browsertab.dropafterr { box-shadow: inset -3px 0 0 #fff; }

#newtab {
    width: 28px; height: 28px; margin: 0 0 3px 4px; align-self: flex-end;
    border-radius: 50%; color: #fff; font-size: 18px; background: transparent;
}
#newtab:hover { background: var(--jlchover); }

#topbar { position: relative; z-index: 1; gap: 4px; min-height: 40px; padding: 4px 8px; background: var(--maincolorr); }
#topbar button { background: transparent; color: #fff; transform: none; transition: none; }
#topbar button:hover { background: var(--jlchover); transform: none; }
.navbuttons, .thebuttonthatnavigates { gap: 0; }
.toolbaractions { gap: 0; }
.taskbutton { width: 32px; height: 32px; border-radius: 50%; font-size: 16px; }

#urlbar { height: 34px; margin: 0 4px; padding: 0 14px; border-radius: 17px; background: var(--colorforbtns); }
#urlbar:focus-within { box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--textforbtns) 75%, transparent); }
#favicon { width: 16px; height: 16px; margin-right: 10px; border-radius: 2px; }
#urlinput { font-size: 14px; font-family: var(--jlcfont); color: var(--textforbtns); }
#urlinput:focus { color: var(--textforbtns); }
#urlinput::placeholder { color: color-mix(in srgb, var(--textforbtns) 55%, transparent); }

#bookmarkrow { min-height: 34px; padding: 2px 8px 4px; gap: 0; background: var(--maincolorr); box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.3); }
#bookmarklist { gap: 2px; }
.bookmarkitem { height: 28px; padding: 0 8px; border-radius: 14px; color: #fff; font: 12px var(--jlcfont); }
.bookmarkitem:hover { background: var(--jlchover); }

#boomaradd, #prompttext { background: rgba(0, 0, 0, 0.5); backdrop-filter: none; }
#bookmarkbox, #promptthing {
    gap: 16px; width: min(380px, 90vw); padding: 24px; border-radius: 12px;
    color: var(--textforbtns); background: var(--colorwhenuse); box-shadow: 0 8px 32px rgba(0, 0, 0, 0.45);
}
#bookmarkbox h3, #promptthing h3 { font: 400 18px var(--jlcfont); color: var(--textforbtns); }
#putbookmname, #putbookmaddy, #promptuserbox {
    padding: 10px 12px; border: 1px solid color-mix(in srgb, var(--textforbtns) 45%, transparent);
    border-radius: 8px; background: transparent; color: var(--textforbtns); font: 14px var(--jlcfont);
}
#putbookmname:focus, #putbookmaddy:focus, #promptuserbox:focus {
    border-color: var(--textforbtns); box-shadow: 0 0 0 1px var(--textforbtns);
}
#bookmarkcancel, #bookmarksave, #promptcancl, #promptconff {
    padding: 9px 18px; border-radius: 18px; font: 500 13px var(--jlcfont);
}
#bookmarkcancel, #promptcancl { color: var(--textforbtns); background: transparent; }
#bookmarkcancel:hover, #promptcancl:hover { background: color-mix(in srgb, var(--textforbtns) 14%, transparent); }
#bookmarksave, #promptconff { color: var(--colorwhenuse); background: var(--textforbtns); }
#bookmarksave:hover, #promptconff:hover { filter: brightness(1.1); }

#hoverthingyyfortab {
    border: 1px solid color-mix(in srgb, var(--textforbtns) 25%, transparent) !important;
    border-radius: 8px !important; box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35) !important;
    font: 12px "Segoe UI", system-ui, Arial, sans-serif !important;
}
